import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)
    q = next(it)

    arr = [0] * (n + 1)
    bit = [0] * (n + 1)

    def add(i, delta):
        while i <= n:
            bit[i] += delta
            i += i & -i

    def prefix_sum(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    for i in range(1, n + 1):
        val = next(it)
        arr[i] = val
        add(i, val)

    out = []

    for _ in range(q):
        typ = next(it)
        if typ == 0:
            k = next(it)
            p = next(it)
            delta = p - arr[k]
            if delta != 0:
                arr[k] = p
                add(k, delta)
        else:
            k = next(it)
            out.append(str(prefix_sum(k)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
